'use strict';
function leaveBotMatch(){if(!['draft','fight','between','end'].includes(phase))return;phase='idle';globalThis.window?.syncArenaFocus?.();paused=false;actors=[];shots=[];zones=[];effects=[];floating=[];score=[0,0];round=1;clock=120;nextRound=0;input.keys.clear();input.down=false;input.target=null;input.enemy=null;input.selectedEnemy=null;$('#draft').classList.add('hidden');$('#pause').textContent='Ⅱ';$('#start').innerHTML='BOT MAÇINA GİR <span>↗</span>';setKit();updateHud();showBanner('BOT MAÇINDAN ÇIKTIN','Arena seni bekliyor.','Yeni bot maçı başlatabilir veya arkadaşlarınla çevrimiçi oynayabilirsin.');refreshExitButtons();}
function refreshExitButtons(){const playing=['draft','fight','between','end'].includes(phase),online=typeof net!=='undefined'&&net.active,training=!!window.khTrainingRoom?.active,label=online?'RAGE QUIT':training?'DENEME ODASINDAN ÇIK':'BOT MAÇINDAN ÇIK';for(const id of ['#match-exit','#draft-exit']){const button=$(id);button.textContent=label;button.setAttribute('aria-label',online?'Çevrimiçi odadan ayrıl (Rage Quit)':training?'Deneme odasından çık':'Bot maçından çık');button.classList.toggle('hidden',!playing||(id==='#draft-exit')!==(phase==='draft'));}}
for(const id of ['#match-exit','#draft-exit'])$(id).onclick=()=>{if(typeof net!=='undefined'&&net.active)net.disconnect();else leaveBotMatch();refreshExitButtons();};
setInterval(refreshExitButtons,100);
refreshExitButtons();
